sys_script_include.script:
var FeedbackUtilsCS = Class.create();
FeedbackUtilsCS.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getFeedbackDetailsById: function() {
        var _feedbackId = this.getParameter('sysparm_feedbackId');
        return JSON.stringify(new FeedbackUtils().getFeedbackDetailsById(_feedbackId));
    },

    isFeedbackPositive: function() {
        var _feedbackId = this.getParameter('sysparm_feedbackId');
        return JSON.stringify(new FeedbackUtils().isFeedbackPositive(_feedbackId));
    },

    getFeedbackByEvent: function() {
        var _eventId = this.getParameter('sysparm_eventId');
        return JSON.stringify(new FeedbackUtils().getFeedbackByEvent(_eventId));
    },

    type: 'FeedbackUtilsCS'
});
